use cosmolkit_core::{
    Fingerprint, Molecule, PatternFingerprintParams, SmartsParseParams, has_substruct_match, mol_from_smarts,
};

const FP_SIZE: usize = 2048;

#[derive(Clone, Copy)]
enum InputKind {
    Smiles,
    Smarts,
    SmartsMergeHs,
}

struct ScreeningCase {
    case_id: &'static str,
    query_kind: InputKind,
    query: &'static str,
    target: &'static str,
    query_hex: &'static str,
    target_hex: &'static str,
}

fn parse_input(kind: InputKind, input: &str) -> Molecule {
    match kind {
        InputKind::Smiles => Molecule::from_smiles(input).expect("screening SMILES"),
        InputKind::Smarts => mol_from_smarts(input, &SmartsParseParams::default()).expect("screening SMARTS"),
        InputKind::SmartsMergeHs => mol_from_smarts(
            input,
            &SmartsParseParams {
                merge_hs: true,
                ..SmartsParseParams::default()
            },
        )
        .expect("screening SMARTS with merged hydrogens"),
    }
}

fn fingerprint_hex(fingerprint: &Fingerprint) -> String {
    let mut bytes = [0_u8; FP_SIZE / 8];
    for bit in fingerprint.on_bits() {
        bytes[bit / 8] |= 1 << (bit % 8);
    }
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn all_probe_bits_match(probe: &Fingerprint, target: &Fingerprint) -> bool {
    let target_bits = target.on_bits();
    probe
        .on_bits()
        .into_iter()
        .all(|bit| target_bits.binary_search(&bit).is_ok())
}

fn fingerprint(molecule: &Molecule) -> Fingerprint {
    molecule
        .pattern_fingerprint(&PatternFingerprintParams::default())
        .expect("Pattern fingerprint")
}

