#[test]
fn pinned_upstream_and_project_screening_cases_match_exact_vectors_and_containment() {
    // RDKit✔️✔️: ExplicitBitVect *qbv = PatternFingerprintMol(*qm, 2048);
    // RDKit✔️✔️: ExplicitBitVect *mbv = PatternFingerprintMol(*m, 2048);
    // RDKit✔️✔️: MatchVectType mv;
    // RDKit✔️✔️: TEST_ASSERT(SubstructMatch(*m, *qm, mv));
    // RDKit✔️✔️: TEST_ASSERT(AllProbeBitsMatch(*qbv, *mbv));
    for case in SCREENING_CASES {
        let query = parse_input(case.query_kind, case.query);
        let target = Molecule::from_smiles(case.target)
            .unwrap_or_else(|error| panic!("{} target parse failed: {error}", case.case_id));
        assert!(
            has_substruct_match(&target, &query),
            "{} source-positive substructure match failed",
            case.case_id
        );
        let query_fingerprint = fingerprint(&query);
        let target_fingerprint = fingerprint(&target);
        assert_eq!(
            fingerprint_hex(&query_fingerprint),
            case.query_hex,
            "{} query exact vector differs",
            case.case_id
        );
        assert_eq!(
            fingerprint_hex(&target_fingerprint),
            case.target_hex,
            "{} target exact vector differs",
            case.case_id
        );
        assert!(
            all_probe_bits_match(&query_fingerprint, &target_fingerprint),
            "{} query bits are not contained in the target",
            case.case_id
        );
    }
}

#[test]
fn pinned_single_atom_fragment_regressions_match_exact_vectors() {
    // RDKit✔️✔️: ExplicitBitVect *bv = PatternFingerprintMol(*m1, 2048);
    // RDKit✔️✔️: TEST_ASSERT(bv->getNumOnBits() == 2);
    let chlorine = fingerprint(&Molecule::from_smiles("Cl").expect("chlorine"));
    assert_eq!(chlorine.on_bits(), vec![1061, 1280]);

    // RDKit✔️✔️: TEST_ASSERT(bv->getNumOnBits() == 4);
    let disconnected = fingerprint(&Molecule::from_smiles("Cl.[Na]").expect("fragments"));
    assert_eq!(disconnected.on_bits(), vec![1061, 1236, 1280, 1290]);
}
